"use strict";

const { Sequelize, DataTypes, Model } = require("sequelize");

const sequelize = new Sequelize({
  dialect: "sqlite",
  storage: ":memory:",
  logging: false,
});

class SerializableModel extends Model {
  toJSON() {
    const data = { ...this.get() };
    const hiddenFields = this.constructor.hiddenFields ?? [];

    for (const field of hiddenFields) {
      delete data[field];
    }

    return data;
  }
}

class User extends SerializableModel {
  static associate() {
    this.hasMany(Article, { foreignKey: "userId", onDelete: "CASCADE" });
    this.hasMany(Comment, { foreignKey: "userId" });
  }
}

class Article extends SerializableModel {
  static associate() {
    this.belongsTo(User, { foreignKey: "userId", as: "author" });
    this.hasMany(Comment, { foreignKey: "articleId", onDelete: "cascade" });
  }
}

class Comment extends SerializableModel {
  static associate() {
    this.belongsTo(Article, { foreignKey: "articleId" });
    this.belongsTo(User, { as: "author", foreignKey: "userId" });
  }
}

User.hiddenFields = ["id", "updatedAt", "createdAt"];
Article.hiddenFields = ["id", "userId"];
Comment.hiddenFields = ["articleId", "userId"];

User.init(
  { username: DataTypes.STRING },
  { sequelize, modelName: "User" },
);

Article.init(
  { slug: DataTypes.STRING },
  { sequelize, modelName: "Article" },
);

Comment.init(
  {
    id: {
      allowNull: false,
      autoIncrement: true,
      primaryKey: true,
      type: DataTypes.INTEGER,
    },
    body: DataTypes.TEXT,
  },
  { sequelize, modelName: "Comment" },
);

User.associate();
Article.associate();
Comment.associate();

module.exports = { sequelize, User, Article, Comment };

