import { useEffect, useState } from "react";
import { getComments } from "./api";
import CommentRow from "./CommentRow";

function CommentFeed({ slug }) {
  const [state, setState] = useState({
    comments: [],
    error: null,
    status: "loading",
  });

  useEffect(() => {
    const controller = new AbortController();

    setState({
      comments: [],
      error: null,
      status: "loading",
    });

    getComments(slug, { signal: controller.signal })
      .then((comments) => {
        setState({
          comments,
          error: null,
          status: "ready",
        });
      })
      .catch((err) => {
        if (err.name === "AbortError") {
          return;
        }

        setState({
          comments: [],
          error: err.message,
          status: "error",
        });
      });

    return () => {
      controller.abort();
    };
  }, [slug]);

  if (state.status === "loading") {
    return <p className="loading">Loading comments...</p>;
  }

  if (state.error) return <p className="error">{state.error}</p>;
  if (state.comments.length === 0) return null;

  return (
    <div className="feed">
      {state.comments.map((comment) => (
        <CommentRow key={comment.id} {...comment} />
      ))}
    </div>
  );
}

export default CommentFeed;

